  event.add('ftbchunks.config.server.fake_players.max_prevented_log_age', 'Максимальный возраст логов предотвращённого доступа фейковых игроков')
  event.add('ftbchunks.config.server.fake_players.max_prevented_log_age.tooltip', 'Возраст в днях для хранения логов предотвращённого доступа фейковых игроков\nПримечание: не полностью реализованная функция; будет использоваться в будущем для отображения и контроля доступа фейковых игроков к вашим захватам')
  event.add('ftbchunks.config.server.fire_spread_protection', 'Защита от распространения огня')
  event.add('ftbchunks.config.server.fire_spread_protection.tooltip', 'Если это правда, пожар не распространяется на заявки, принадлежащие различным командам (если только для целевой заявки не определены общедоступные разрешения «редактировать блок»).\nЛожь по умолчанию; включение этого параметра потенциально может привести к проблемам с производительностью сервера, особенно когда много блоков горят.\nЕсли для параметра «disable_protection» установлено значение true, этот параметр игнорируется.')
  event.add('ftbchunks.config.server.flowing_fluid_protection', 'Защита от протекающей жидкости')
  event.add('ftbchunks.config.server.flowing_fluid_protection.tooltip', 'Если это правда, потоки не могут перемещаться по горизонтали между утверждениями, принадлежащими различным командам (если только для целевого утверждения не определены общедоступные разрешения «редактировать блок»).\nЛожь по умолчанию; включение этого параметра потенциально может привести к проблемам с производительностью сервера, поскольку тики потока жидкости проверяются очень часто, особенно для больших объемов текущих жидкостей.\nЕсли для параметра «disable_protection» установлено значение true, этот параметр игнорируется.')
  event.add('ftbchunks.config.server.force_disable_minimap', 'Отключить миникарту для клиентов')
  event.add('ftbchunks.config.server.force_loading', 'Принудительная загрузка')
  event.add('ftbchunks.config.server.force_loading.force_load_mode', 'Режим принудительной загрузки в оффлайне')
  event.add('ftbchunks.config.server.force_loading.force_load_mode.tooltip', 'НИКОГДА: разрешать принудительную загрузку чанков только если у команды есть хотя бы один онлайн-игрок\nВСЕГДА: всегда разрешать принудительную загрузку, даже если нет онлайн-игроков\nПО УМОЛЧАНИЮ: разрешать принудительную загрузку, ЕСЛИ у команды есть хотя бы один игрок с разрешением FTB Ranks \'ftbchunks.chunk_load_offline\'')
  event.add('ftbchunks.config.server.force_loading.hard_team_force_limit', 'Жёсткий лимит принудительной загрузки для команды')
