  event.add('gui.xaero_box_biome_blending', 'Сглаживайте края цвета биома, выбирая цвета биома для нескольких блоков для каждого блока на карте. Отключение этого параметра может значительно улучшить производительность, когда расчет цвета биома модифицирован так, чтобы он был намного более тяжелым, чем в стандартном варианте.')
  event.add('gui.xaero_box_category_include_list_include_in_super2', 'Автоматически включать все элементы из этого списка и других подсписков, включенных в эту категорию, в суперкатегорию/родительскую категорию этой категории. Таким образом, вам не придется вручную добавлять дубликаты на каждом уровне. Имейте в виду, что суперкатегории не будут проверять списки исключений этой категории.')
  event.add('gui.xaero_box_cave_mode_allowed', 'Режим картирования, который может проникать глубже поверхностных блоков, в основном для отображения подземных пещер и интерьеров зданий. Режим пещеры обычно включается автоматически (см. «Режим автоматического пещеры»), но его также можно переключить вручную с помощью нажатия клавиши (см. «Запуск ручного режима пещеры Y»).')
  event.add('gui.xaero_box_cave_mode_allowed_dimensions', 'Список идентификаторов измерений, разделенных запятыми, в которых должен работать режим пещеры. Если список пуст (просто []), режим пещеры работает во всех измерениях.')
  event.add('gui.xaero_box_cave_mode_toggle_timer', 'Минимальное время ожидания между переключениями режима пещеры для предотвращения мерцания при быстром переключении между нахождением под блоками и без них. В моде Xaero\'s World Map для этого есть отдельная настройка.')
  event.add('gui.xaero_box_compass', 'Отображение сторон света на мини-карте.')
  event.add('gui.xaero_box_compass_color', 'Цвет фона/тени под сторонами света, отображаемых на мини-карте.')
  event.add('gui.xaero_box_compass_scale2', 'Масштаб букв сторон света (С, В, Ю, З). Для значения «Авто» передвиньте ползунок максимально влево.')
  event.add('gui.xaero_box_dimension_scaled_max_waypoint_distance', 'Масштабируйте максимальное расстояние отрисовки путевой точки по шкале координат текущего измерения (например, 1/8 в Пустоте).')
  event.add('gui.xaero_box_discovered_waystone_waypoints', 'Автоматически отображать обнаруженные путевые камни (из модов Waystones и Wraith Waystones) как путевые точки. В Wraith Waystones обнаруженными считаются только активированные.')
  event.add('gui.xaero_box_entity_radar_categories', 'Настраивайте определенные категории объектов, которыми обычно являются игроки, враждебные мобы, дружественные мобы, предметы или другие объекты, отдельно, вместо того, чтобы иметь одну и ту же конфигурацию для каждого объекта. Вы даже можете создавать свои собственные категории для определенных типов объектов.')
  event.add('gui.xaero_box_further_zoomout', 'Экспериментально! \n Не включено по умолчанию из-за потенциально плохой производительности, но будет включено в будущем после некоторой оптимизации.')
  event.add('gui.xaero_box_info_display_background_opacity', 'Непрозрачность цветных фонов элементов информации, у которых в менеджере отображения информации включен фон.')
  event.add('gui.xaero_box_legible_cave_maps', 'Использование в режиме пещеры освещения, основанного на глубине, вместо фактического освещения блоков облегчает мысленное разделение различных слоев пещеры.')
  event.add('gui.xaero_box_map_distances', 'Отображение расстояний до позиций или элементов на карте, по которым вы щелкаете правой кнопкой мыши. Для позиций расстояние отображается в двух измерениях. Для таких элементов, как путевые точки и отслеживаемые игроки, они, где это применимо, являются трехмерными.')
  event.add('gui.xaero_box_minimap_info_display_manager', 'Настраивайте и/или изменяйте порядок различных типов информации, отображаемой на мини-карте, такой как текущие координаты, углы обзора, размеры, биом, погода, уровень освещенности, игровое время, реальное время и многое другое.')
  event.add('gui.xaero_box_minimap_item', 'Идентификатор элемента, который требуется на панели быстрого доступа для работы мини-карты и путевых точек. Установите значение «-», чтобы не иметь требований к предмету.')
