  event.add('modernfix.option.mixin.bugfix.buffer_builder_leak', 'Попытки обойти моды, создающие объекты BufferBuilder, которые вызывают утечку памяти. В некоторых редких случаях это может привести к сбою JVM с файлом hs_err_pid. Если у вас произошел сбой такого типа, попробуйте отключить эту опцию.')
  event.add('modernfix.option.mixin.bugfix.extra_experimental_screen', 'Исправлено предупреждение об экспериментальной функции, которое по-прежнему отображалось при первом повторном открытии мира, который был создан как экспериментальный.')
  event.add('modernfix.option.mixin.bugfix.forge_at_inject_error', 'Исправляет серьезную ошибку в раннем коде обработки ошибок Forge, из-за которой некоторые части модов загружаются, но не другие, что обычно приводит к сбою игры, а не к отображению предполагаемого экрана ошибки. Эта проблема была исправлена ​​в NeoForge и в конечном итоге исправлена ​​в достаточно новых версиях Forge.')
  event.add('modernfix.option.mixin.bugfix.missing_block_entities', 'Hypixel отправляет клиенту фрагменты, в которых отсутствуют некоторые данные объекта блока, из-за чего сундуки и т. д. кажутся невидимыми. Это «решает» проблему, создавая необходимые данные на клиенте. Не имеет никакого влияния на правильное поведение серверов или в одиночной игре.')
  event.add('modernfix.option.mixin.bugfix.restore_old_dragon_movement', 'Исправление MC-272431, из-за которого дракон Края не мог нырнуть к порталу, как это было в версии 1.13 и старше. Это заставляет дракона летать совсем не так, как привыкли современные игроки, а также исправляет один цикл, поэтому по умолчанию он не включен. Спасибо Jukitsu за обнаружение регрессии в ванильном коде.')
  event.add('modernfix.option.mixin.bugfix.world_screen_skipped', 'Исправление MC-251068, из-за которого удаление последнего мира возвращало вас к пустому списку миров.')
  event.add('modernfix.option.mixin.feature.blockentity_incorrect_thread', '**Это опция отладки, и ее не следует включать в обычном игровом процессе.** Пытается обнаружить моды, взаимодействующие с блокирующими объектами в неправильном потоке, и приводит к сбою игры с дополнительной информацией, а не с неясным исключением ConcurrentModificationException.')
  event.add('modernfix.option.mixin.feature.cause_lag_by_disabling_threads', 'Отключает использование игрой рабочих потоков для сервера и для рендеринга фрагментов. **Это ухудшит производительность практически на всех устройствах**, и его следует включать на клиенте только тогда, когда вы точно знаете, что делаете, и, вероятно, только на оборудовании с очень небольшим количеством (2 или меньше) физических ядер ЦП. В этих редких случаях это может уменьшить скачки задержки, поскольку меньше конфликтов из-за ограниченного количества ядер.')
  event.add('modernfix.option.mixin.feature.registry_event_progress', 'Запускает экран загрузки Forge в фоновом потоке для части процесса загрузки, чтобы отображать ход выполнения во время регистрации контента. Могут возникнуть проблемы совместимости с некоторыми драйверами графического процессора (например, macOS), поэтому не включайте его по умолчанию в модпаке.')
  event.add('modernfix.option.mixin.feature.remove_chat_signing', 'Не позволяет клиенту Minecraft получить пару ключей для подписи в чате. Это отключает возможность клиента подписывать сообщения чата (например, «Отчеты об отсутствии чата», но более простым, хотя и менее удобным для пользователя способом).')
  event.add('modernfix.option.mixin.feature.remove_telemetry', 'Запрещает клиенту Minecraft отправлять телеметрию в Mojang. Телеметрия, как правило, не имеет к ним отношения в любом случае для модифицированного экземпляра.')
  event.add('modernfix.option.mixin.feature.suppress_narrator_stacktrace', 'Предотвращает регистрацию в игре очень длинной трассировки стека, когда рассказчик не загружается в Linux (обычно это происходит из-за отсутствия установленной библиотеки libflite).')
  event.add('modernfix.option.mixin.perf.chunk_meshing', 'Реализованы некоторые незначительные оптимизации в логике построения сетки ванильных фрагментов (они не будут иметь никакого эффекта с модом, который полностью заменяет рендеринг фрагментов).')
  event.add('modernfix.option.mixin.perf.compress_unihex_font', 'Более эффективно сохраняет глифы шрифта Unicode. Спасибо @AnAwesomGuy за трюк.')
  event.add('modernfix.option.mixin.perf.dynamic_resources.ldlib', 'Исправление совместимости LDLib для динамических ресурсов.')
  event.add('modernfix.option.mixin.perf.faster_structure_location', 'Улучшает скорость обнаружения таких структур, как зарытые сокровища.')
  event.add('modernfix.option.mixin.perf.forge_registry_alloc', 'Исправлено больше ошибок в Forge, которые приводили к чрезмерному выделению ресурсов в горячих методах реестра.')
  event.add('modernfix.option.mixin.perf.memoize_creative_tab_build', 'Улучшает существующее в Vanilla кэширование содержимого творческих вкладок таким образом, чтобы оно соответствовало требованиям синхронизации таких модов, как JEI/EMI. Это может уменьшить скачок задержки при первом открытии творческого инвентаря в модпаке.')
  event.add('modernfix.option.mixin.perf.potential_spawns_alloc', 'Оптимизирует событие «Кузница» для поиска потенциальных мобов, которые могут появиться. Это уменьшает распределение и затраты на перестроение взвешенного списка, когда никакие моды не изменяют потенциальные места появления.')
  event.add('modernfix.option.mixin.perf.ticking_chunk_alloc', 'Оптимизирует тиканье чанков в ванили для уменьшения выделения ресурсов.')
  event.add('modernfix.option.mixin.perf.worldgen_allocation', 'Оптимизирует некоторую логику генерации мира в ванильной версии, чтобы уменьшить выделение объектов.')
  event.add('modernfix.redirector_installed', 'ModernFix обнаружил, что Redirector установлен. Известно, что редиректор вызывает множество странных и трудно отлаживаемых проблем, поэтому настоятельно рекомендуется его удалить.')
