  event.add('sodium-extra.option.protected_gameplay_fog.powder_snow.tooltip', 'Регулирует порошковый снежный туман, когда это позволяет локальная игра или сервер разрешает это с помощью Greenlight.\n0: использовать настройки ванильного тумана.\n1+: установить расстояние тумана в блоках; снег из ванильного порошка составляет около 2 блоков\nВыкл.: отключить этот туман.')
  event.add('sodium-extra.option.protected_gameplay_fog.tooltip', 'Позволяет расширенное изменение расстояния тумана для тумана, влияющего на игровой процесс, в частных одиночных мирах, мирах локальной сети с включенными читами или на серверах, которые авторизуют это через Greenlight. Для многопользовательской авторизации требуется установленный Greenlight. Эти элементы управления используют расстояния между блоками.')
  event.add('sodium-extra.option.protected_gameplay_fog.water', 'Водяной туман')
  event.add('sodium-extra.option.protected_gameplay_fog.water.tooltip', 'Регулирует подводный туман, когда это позволяет локальная игра или сервер разрешает это с помощью Greenlight.\n0: использовать настройки ванильного тумана.\n1+: установить расстояние тумана в блоках; Ванильная вода зависит от биома и водного видения\nВыкл.: отключить этот туман.')
  event.add('sodium-extra.option.wayland_fullscreen_resolution', 'Разрешение полноэкранного режима Wayland/XWayland')
  event.add('sodium-extra.option.wayland_fullscreen_resolution.confirm.keep', 'Keep')
