  event.add('sodium-extra.option.wayland_fullscreen_resolution.confirm.message', 'Это разрешение является экспериментальным для Wayland/XWayland и может отображаться неправильно. Если вы можете это прочитать, выберите «Сохранить». Если экран черный или непригоден для использования, ничего не делайте — предыдущее разрешение будет восстановлено автоматически.')
  event.add('sodium-extra.option.wayland_fullscreen_resolution.confirm.revert', 'Вернуть сейчас')
  event.add('sodium-extra.option.wayland_fullscreen_resolution.confirm.title', 'Сохранить это полноэкранное разрешение?')
  event.add('sodium-extra.option.wayland_fullscreen_resolution.tooltip', 'Позволяет использовать полноэкранное управление разрешением Sodium на Wayland или XWayland. Real X11 включает это автоматически; Поддержка Wayland и XWayland является экспериментальной, поскольку поведение зависит от композитора. Если выбранный режим препятствует чистому запуску игры, Sodium Extra отключит эту опцию и сбросит полноэкранный режим при следующем запуске.')
